assertion.value:
// Полный контракт кейса из eval/cases/roles.jsonl.
// Проверяются: must_contain, must_not_contain, expected_fields,
// дисциплина режима (auto/chat/hybrid).
let contract = {};
try { contract = JSON.parse(context.vars.contract || '{}'); } catch (e) { contract = {}; }
const out = output || '';
const lower = out.toLowerCase();
const problems = [];

for (const needle of (contract.must_contain || [])) {
  if (!lower.includes(String(needle).toLowerCase())) {
    problems.push(`must_contain отсутствует: "${needle}"`);
  }
}
for (const needle of (contract.must_not_contain || [])) {
  if (lower.includes(String(needle).toLowerCase())) {
    problems.push(`must_not_contain присутствует: "${needle}"`);
  }
}
for (const field of (contract.expected_fields || [])) {
  if (!(out.includes(`"${field}"`) || out.includes(`${field}:`))) {
    problems.push(`нет обязательного поля: ${field}`);
  }
}

// Ответ должен быть на русском: кириллица обязательна. Иначе модель
// уходит в другой язык (наблюдалось у qwen: китайский), и ответ
// непригоден для воркшопа, даже если поля формально на месте.
const cyrillic = (out.match(/[А-Яа-яЁё]/g) || []).length;
if (cyrillic < 20) problems.push('ответ не на русском языке (нет кириллицы)');

const count = (s, sub) => s.split(sub).length - 1;
const modeCheck = contract.mode_check;
if (modeCheck === 'auto_no_questions') {
  if (out.includes('Зачем я это спрашиваю')) {
    problems.push('auto: задан вопрос, хотя auto = 0 вопросов');
  }
} else if (modeCheck === 'chat_three_blocks') {
  for (const block of ['Вопрос', 'Зачем я это спрашиваю', 'Термины']) {
    if (!out.includes(block)) problems.push(`chat: нет блока "${block}"`);
  }
  if (count(out, 'Вопрос') > 3) problems.push('chat: больше 3 вопросов за гейт');
} else if (modeCheck === 'hybrid_forks_only') {
  if (out.includes('Вопрос')) {
    const forks = ['контур', 'пользовател', 'платеж', 'интеграц'];
    if (!forks.some((f) => lower.includes(f))) {
      problems.push('hybrid: вопрос не про критичную развилку');
    }
  }
}

if (problems.length === 0) {
  return { pass: true, score: 1, reason: 'контракт выполнен' };
}
return { pass: false, score: 0, reason: problems.join('; ') };

